conformance('C1-C9 certify a displayed instance without operational open-query fidelity', [
  spec('11.6, 11.8, 11.13'),
  args("--strict-proof --check-proof proof.js --goal 'q(X)' program.js"),
  exit(2),
  file('program.js', [
    "fact(p('a'), p('b'))",
    'implied_by(q(X), once(p(X)))',
  ]),
  file('proof.js', [
    "q('b')",
    "step(q('b'), clause(3), {}, [once(p('b'))])",
    "step(once(p('b')), 'control', {}, [p('b')])",
  ]),
  stdout([
    '// Unverified claims: proof checking failed.',
    "q('b')",
    '',
    '// C1-C10: resolution, acyclicity, justification, coverage, re-decision,',
    '// boundary consistency, relevance, witness integrity, search closure and call fidelity.',
    "condition('C1', 'resolution', 'ok', 1)",
    "condition('C2', 'well_founded', 'ok', 2)",
    "condition('C3', 'justification', 'ok', 2)",
    "condition('C4', 'coverage', 'ok', 3)",
    "condition('C5', 're_decision', 'ok', 1)",
    "condition('C6', 'boundary_consistency', 'ok', 0)",
    "condition('C7', 'relevance', 'ok', 3)",
    "condition('C8', 'witness_integrity', 'ok', 0)",
    "condition('C9', 'search_closure', 'ok', 0)",
    "condition('C10', 'call_fidelity', failed(1), 0)",
    '',
    '// Failures: the claims above have not passed every check.',
    "failure('C10', q('b'), …)",
    '',
    '// Obligations: absence, collection or original-call evidence remains unproved.',
    "obligation('call_fidelity', 'original_call', q('b'))",
    '',
    '// Proof statistics: recorded steps and how they were checked.',
    'steps(2)',
    'verified(1)',
    'recomputed(0)',
    'composed(1)',
    'trusted(1)',
    'claims(1)',
    '',
    '// This verdict applies to the claims above; it does not establish completeness.',
    'verdict(failed(1))',
  ]),
])

