conformance('C3: an invalid collection is not a strict-proof obligation', [
  spec('11.4, 11.6, 12'),
  args('--strict-proof --check-proof proof.js program.js'),
  exit(2),
  file('program.js', [
    'implies(findall(X, missing, L), q)',
  ]),
  file('proof.js', [
    "'q'",
    "step('q', clause(1), {}, [findall(A, 'missing', [])])",
    "step(findall(A, 'missing', []), 'collected', {}, ['true'])",
    "step('true', 'builtin', {}, [])",
  ]),
  stdout([
    '// Unverified claims: proof checking failed.',
    "'q'",
    '',
    '// C1-C10: resolution, acyclicity, justification, coverage, re-decision,',
    '// boundary consistency, relevance, witness integrity, search closure and call fidelity.',
    "condition('C1', 'resolution', 'ok', 1)",
    "condition('C2', 'well_founded', 'ok', 3)",
    "condition('C3', 'justification', failed(1), 3)",
    "condition('C4', 'coverage', 'ok', 3)",
    "condition('C5', 're_decision', 'ok', 1)",
    "condition('C6', 'boundary_consistency', 'ok', 0)",
    "condition('C7', 'relevance', 'ok', 4)",
    "condition('C8', 'witness_integrity', 'ok', 0)",
    "condition('C9', 'search_closure', 'ok', 0)",
    "condition('C10', 'call_fidelity', failed(1), 0)",
    '',
    '// Failures: the claims above have not passed every check.',
    "failure('C3', findall(A, 'missing', []), …)",
    "failure('C10', 'q', …)",
    '',
    '// Obligations: absence, collection or original-call evidence remains unproved.',
    "obligation('call_fidelity', 'original_call', 'q')",
    '',
    '// Proof statistics: recorded steps and how they were checked.',
    'steps(3)',
    'verified(1)',
    'recomputed(1)',
    'composed(0)',
    'trusted(1)',
    'claims(1)',
    '',
    '// This verdict applies to the claims above; it does not establish completeness.',
    'verdict(failed(2))',
  ]),
])

conformance('C9: shared table dependencies preserve every collection ordering obligation', [
  spec('11.10, 12'),
  args('--check-proof proof.js program.js'),
  file('program.js', [
    'fact(seed(1), seed(2))',
    'implies(seed(X), f(X))',
    'implied_by(c(X), f(X))',
    'implied_by(a(X), c(X))',
    'implied_by(d(X), c(X))',
    'implied_by(b(X), d(X))',
    'implied_by(root(X), or(a(X), b(X)))',
    'implies(findall(X, root(X), L), allroot(L))',
    'implies(findall(X, a(X), L), alla(L))',
  ]),
  file('proof.js', [
    'f(1)',
    'f(2)',
    'allroot([1, 2, 1, 2])',
    'alla([1, 2])',
    'step(f(1), clause(3), {X: 1}, [seed(1)])',
    'step(f(2), clause(3), {X: 2}, [seed(2)])',
    'step(allroot([1, 2, 1, 2]), clause(9), {X: A, L: [1, 2, 1, 2]}, [findall(A, root(A), [1, 2, 1, 2])])',
    "step(findall(A, root(A), [1, 2, 1, 2]), 'collected', {}, [])",
    'step(alla([1, 2]), clause(10), {X: B, L: [1, 2]}, [findall(B, a(B), [1, 2])])',
    "step(findall(B, a(B), [1, 2]), 'collected', {}, [])",
    'derived(f(Z), [f(1), f(2)])',
    'searched(root(Z), [root(1), root(2), root(1), root(2)])',
    'searched(a(Z), [a(1), a(2)])',
    'searched(b(Z), [b(1), b(2)])',
    'searched(c(Z), [c(1), c(2)])',
    'searched(d(Z), [d(1), d(2)])',
    'searched(f(Z), [f(1), f(2)])',
  ]),
  stdout([
    '// Answers checked subject to the obligations below.',
    'f(1)',
    'f(2)',
    'allroot([1, 2, 1, 2])',
    'alla([1, 2])',
    '',
    '// C1-C10: resolution, acyclicity, justification, coverage, re-decision,',
    '// boundary consistency, relevance, witness integrity, search closure and call fidelity.',
    "condition('C1', 'resolution', 'ok', 4)",
    "condition('C2', 'well_founded', 'ok', 6)",
    "condition('C3', 'justification', 'ok', 6)",
    "condition('C4', 'coverage', 'ok', 8)",
    "condition('C5', 're_decision', 'ok', 0)",
    "condition('C6', 'boundary_consistency', 'ok', 0)",
    "condition('C7', 'relevance', 'ok', 10)",
    "condition('C8', 'witness_integrity', 'ok', 0)",
    "condition('C9', 'search_closure', 'ok', 0)",
    "condition('C10', 'call_fidelity', 'ok', 0)",
    '',
    '// Obligations: absence, collection or original-call evidence remains unproved.',
    "obligation('collected', 'theory_scoped', findall(A, root(A), [1, 2, 1, 2]))",
    "obligation('collected', 'theory_scoped', findall(A, a(A), [1, 2]))",
    "obligation('call_fidelity', 'original_call', f(1))",
    "obligation('call_fidelity', 'original_call', f(2))",
    "obligation('call_fidelity', 'original_call', allroot([1, 2, 1, 2]))",
    "obligation('call_fidelity', 'original_call', alla([1, 2]))",
    '',
    '// Proof statistics: recorded steps and how they were checked.',
    'steps(6)',
    'verified(4)',
    'recomputed(0)',
    'composed(0)',
    'trusted(6)',
    'claims(4)',
    '',
    '// This verdict applies to the claims above; it does not establish completeness.',
    "verdict('checked_with_obligations')",
  ]),
])

conformance('a valid proof is checked', [
  spec('11, 12'),
  args('--check-proof proof.js program.js'),
  file('program.js', [
    "fact(p('a'))",
    'implies(p(X), q(X))',
    'implies(q(X), r(X))',
  ]),
  file('proof.js', [
    "q('a')",
    "r('a')",
    "",
    "clause(1, fact(p('a')))",
    'clause(2, implies(p(X), q(X)))',
    'clause(3, implies(q(X), r(X)))',
    "",
    "step(q('a'), clause(2), {X: 'a'}, [p('a')])",
    "step(p('a'), clause(1), {}, [])",
    "step(r('a'), clause(3), {X: 'a'}, [q('a')])",
    "derived(q(A), [q('a')])",
    "derived(r(B), [r('a')])",
    "called(q(C), [q('a')])",
    "called(r(D), [r('a')])",
  ]),
  stdout([
    "// Checked answers: these follow from the input program.",
    "q('a')",
    "r('a')",
    "",
    '// C1-C10: resolution, acyclicity, justification, coverage, re-decision,',
    '// boundary consistency, relevance, witness integrity, search closure and call fidelity.',
    "condition('C1', 'resolution', 'ok', 3)",
    "condition('C2', 'well_founded', 'ok', 3)",
    "condition('C3', 'justification', 'ok', 3)",
    "condition('C4', 'coverage', 'ok', 4)",
    "condition('C5', 're_decision', 'ok', 0)",
    "condition('C6', 'boundary_consistency', 'ok', 0)",
    "condition('C7', 'relevance', 'ok', 5)",
    "condition('C8', 'witness_integrity', 'ok', 0)",
    "condition('C9', 'search_closure', 'ok', 0)",
    "condition('C10', 'call_fidelity', 'ok', 2)",
    "",
    "// Proof statistics: recorded steps and how they were checked.",
    "steps(3)",
    "verified(3)",
    "recomputed(0)",
    "composed(0)",
    "trusted(0)",
    "claims(2)",
    "",
    "// This verdict applies to the claims above; it does not establish completeness.",
    "verdict('checked')",
  ]),
])

