    '// boundary consistency, relevance, witness integrity, search closure and call fidelity.',
    "condition('C1', 'resolution', 'ok', 5)",
    "condition('C2', 'well_founded', 'ok', 8)",
    "condition('C3', 'justification', 'ok', 8)",
    "condition('C4', 'coverage', 'ok', 8)",
    "condition('C5', 're_decision', 'ok', 0)",
    "condition('C6', 'boundary_consistency', 'ok', 1)",
    "condition('C7', 'relevance', 'ok', 11)",
    "condition('C8', 'witness_integrity', 'ok', 0)",
    "condition('C9', 'search_closure', 'ok', 0)",
    "condition('C10', 'call_fidelity', 'ok', 0)",
    "",
    '// Obligations: absence, collection or original-call evidence remains unproved.',
    "obligation('absent', 'theory_scoped', not(blocked(1)))",
    "obligation('absent', 'theory_scoped', not(blocked(2)))",
    "obligation('collected', 'theory_scoped', findall(A, p(A), [1, 2]))",
    "obligation('call_fidelity', 'original_call', ok(1))",
    "obligation('call_fidelity', 'original_call', ok(2))",
    "obligation('call_fidelity', 'original_call', all_of([1, 2]))",
