conformance('a generated proof checks', [
  spec('8.7, 11'),
  args('--check-proof proof.js program.js'),
  file('program.js', [
    'fact(n(1), n(3))',
    'implies([n(X), gt(X, 2)], big(X))',
  ]),
  file('proof.js', [
    "big(3)",
    "",
    'clause(2, fact(n(3)))',
    'clause(3, implies([n(X), gt(X, 2)], big(X)))',
    "",
    'step(big(3), clause(3), {X: 3}, [n(3), gt(3, 2)])',
    'step(n(3), clause(2), {}, [])',
    "step(gt(3, 2), 'builtin', {}, [])",
  ]),
  stdout([
    '// Answers checked subject to the obligations below.',
    "big(3)",
    "",
    '// C1-C10: resolution, acyclicity, justification, coverage, re-decision,',
    '// boundary consistency, relevance, witness integrity, search closure and call fidelity.',
    "condition('C1', 'resolution', 'ok', 2)",
    "condition('C2', 'well_founded', 'ok', 3)",
    "condition('C3', 'justification', 'ok', 3)",
    "condition('C4', 'coverage', 'ok', 3)",
    "condition('C5', 're_decision', 'ok', 1)",
    "condition('C6', 'boundary_consistency', 'ok', 0)",
    "condition('C7', 'relevance', 'ok', 4)",
    "condition('C8', 'witness_integrity', 'ok', 0)",
    "condition('C9', 'search_closure', 'ok', 0)",
    "condition('C10', 'call_fidelity', 'ok', 0)",
    "",
    '// Obligations: absence, collection or original-call evidence remains unproved.',
    "obligation('call_fidelity', 'original_call', big(3))",
    "",
    "// Proof statistics: recorded steps and how they were checked.",
    "steps(3)",
    "verified(2)",
    "recomputed(1)",
    "composed(0)",
    'trusted(1)',
    "claims(1)",
    "",
    "// This verdict applies to the claims above; it does not establish completeness.",
    "verdict('checked_with_obligations')",
  ]),
])

conformance('C8: each witness is the skolem term of its own firing', [
  spec('11.9'),
  args('--check-proof proof.js program.js'),
  file('program.js', [
    "fact(person('ann'), person('bob'))",
    'implies(person(X), has_parent(X, P))',
  ]),
  file('proof.js', [
    "has_parent('ann', skolem(3, 'P', ['ann']))",
    "has_parent('bob', skolem(3, 'P', ['bob']))",
    "",
    "clause(1, fact(person('ann')))",
    "clause(2, fact(person('bob')))",
    'clause(3, implies(person(X), has_parent(X, P)))',
    "",
    "step(has_parent('ann', skolem(3, 'P', ['ann'])), clause(3), {X: 'ann', P: skolem(3, 'P', ['ann'])}, [person('ann')])",
    "step(person('ann'), clause(1), {}, [])",
    "step(has_parent('bob', skolem(3, 'P', ['bob'])), clause(3), {X: 'bob', P: skolem(3, 'P', ['bob'])}, [person('bob')])",
    "step(person('bob'), clause(2), {}, [])",
  ]),
  stdout([
    '// Answers checked subject to the obligations below.',
    "has_parent('ann', skolem(3, 'P', ['ann']))",
    "has_parent('bob', skolem(3, 'P', ['bob']))",
    "",
    '// C1-C10: resolution, acyclicity, justification, coverage, re-decision,',
    '// boundary consistency, relevance, witness integrity, search closure and call fidelity.',
    "condition('C1', 'resolution', 'ok', 4)",
    "condition('C2', 'well_founded', 'ok', 4)",
    "condition('C3', 'justification', 'ok', 4)",
    "condition('C4', 'coverage', 'ok', 4)",
    "condition('C5', 're_decision', 'ok', 0)",
    "condition('C6', 'boundary_consistency', 'ok', 0)",
    "condition('C7', 'relevance', 'ok', 6)",
    "condition('C8', 'witness_integrity', 'ok', 2)",
    "condition('C9', 'search_closure', 'ok', 0)",
    "condition('C10', 'call_fidelity', 'ok', 0)",
    "",
    '// Obligations: absence, collection or original-call evidence remains unproved.',
    "obligation('call_fidelity', 'original_call', has_parent('ann', skolem(3, 'P', ['ann'])))",
    "obligation('call_fidelity', 'original_call', has_parent('bob', skolem(3, 'P', ['bob'])))",
    "",
    "// Proof statistics: recorded steps and how they were checked.",
    "steps(4)",
    "verified(4)",
    "recomputed(0)",
    "composed(0)",
    'trusted(2)',
    "claims(2)",
    "",
    "// This verdict applies to the claims above; it does not establish completeness.",
    "verdict('checked_with_obligations')",
  ]),
])

