conformance("each kind of step is counted in its own statistic", [
  spec("11.11, 12"),
  args("--check-proof proof.js --goal 'q(X)' program.js"),
  file('program.js', [
    "fact(p(1))",
    "implies(a(X), c(X))",
    "implied_by(q(X), [p(X), lt(X, 2), call(p(X)), not(z(X)), findall(Y, p(Y), L), implies(a(V), c(V))])",
    "implied_by(z(X), w(X))",
    "implied_by(p(X), w(X))",
  ]),
  file('proof.js', [
    "q(1)",
    "",
    "step(q(1), clause(3), {X: 1, L: [1]}, [p(1), lt(1, 2), call(p(1)), not(z(1)), findall(Y, p(Y), [1]), implies(a(A), c(A))])",
    "step(p(1), clause(1), {}, [])",
    "step(lt(1, 2), 'builtin', {}, [])",
    "step(call(p(1)), 'control', {}, [p(1)])",
    "step(not(z(1)), 'absent', {}, [])",
    "step(findall(Y, p(Y), [1]), 'collected', {}, [])",
    "step(implies(a(A), c(A)), source(2), {}, [])",
  ]),
  stdout([
    "// Answers checked subject to the obligations below.",
    "q(1)",
    "",
    '// C1-C10: resolution, acyclicity, justification, coverage, re-decision,',
    '// boundary consistency, relevance, witness integrity, search closure and call fidelity.',
    "condition('C1', 'resolution', 'ok', 3)",
    "condition('C2', 'well_founded', 'ok', 7)",
    "condition('C3', 'justification', 'ok', 7)",
    "condition('C4', 'coverage', 'ok', 8)",
    "condition('C5', 're_decision', 'ok', 2)",
    "condition('C6', 'boundary_consistency', 'ok', 1)",
    "condition('C7', 'relevance', 'ok', 8)",
    "condition('C8', 'witness_integrity', 'ok', 0)",
    "condition('C9', 'search_closure', 'ok', 0)",
    "condition('C10', 'call_fidelity', 'ok', 0)",
    "",
    '// Obligations: absence, collection or original-call evidence remains unproved.',
    "obligation('absent', 'theory_scoped', not(z(1)))",
    "obligation('collected', 'theory_scoped', findall(A, p(A), [1]))",
    "obligation('call_fidelity', 'original_call', q(1))",
    "",
    "// Proof statistics: recorded steps and how they were checked.",
    "steps(7)",
    "verified(3)",
    "recomputed(1)",
    "composed(1)",
    'trusted(3)',
    "claims(1)",
    "",
    "// This verdict applies to the claims above; it does not establish completeness.",
    "verdict('checked_with_obligations')",
  ]),
])

