conformance("failures are listed in the order the report specifies", [
  spec("12"),
  args("--check-proof proof.js program.js"),
  exit(2),
  file('program.js', [
    "fact(p(1))",
    "implies(p(X), q(X))",
    "implies([p(X), not(p(X))], r(X))",
    "implied_by(s(X), s(X))",
  ]),
  file('proof.js', [
    "q(1)",
    "r(1)",
    "z(1)",
    "",
    "clause(1, fact(p(9)))",
    "",
    "step(q(1), clause(2), {X: 1}, [p(1)])",
    "step(r(1), clause(3), {X: 2}, [p(1), not(p(1))])",
    "step(not(p(1)), 'absent', {}, [])",
    "step(lt(2, 1), 'builtin', {}, [])",
    "step(w(1), clause(9), {}, [m(1)])",
    "step(s(1), clause(4), {X: 1}, [s(1)])",
  ]),
  stdout([
    "// Unverified claims: proof checking failed.",
    "q(1)",
    "r(1)",
    "z(1)",
    "",
    '// C1-C10: resolution, acyclicity, justification, coverage, re-decision,',
    '// boundary consistency, relevance, witness integrity, search closure and call fidelity.',
    "condition('C1', 'resolution', failed(3), 2)",
    "condition('C2', 'well_founded', failed(1), 6)",
    "condition('C3', 'justification', 'ok', 6)",
    "condition('C4', 'coverage', failed(2), 8)",
    "condition('C5', 're_decision', failed(1), 0)",
    "condition('C6', 'boundary_consistency', 'ok', 0)",
    "condition('C7', 'relevance', failed(4), 9)",
    "condition('C8', 'witness_integrity', 'ok', 0)",
    "condition('C9', 'search_closure', failed(1), 1)",
    "condition('C10', 'call_fidelity', 'ok', 0)",
    "",
    "// Failures: the claims above have not passed every check.",
    "failure('C1', clause(1, fact(p(9))), …)",
    "failure('C4', z(1), …)",
    "failure('C1', r(1), …)",
    "failure('C5', lt(2, 1), …)",
    "failure('C4', w(1), …)",
    "failure('C1', w(1), …)",
    "failure('C9', not(p(1)), …)",
    "failure('C7', z(1), …)",
    "failure('C7', lt(2, 1), …)",
    "failure('C7', w(1), …)",
    "failure('C7', s(1), …)",
    "failure('C2', s(1), …)",
    "",
    '// Obligations: absence, collection or original-call evidence remains unproved.',
    "obligation('absent', 'theory_scoped', not(p(1)))",
    "obligation('call_fidelity', 'original_call', q(1))",
    "obligation('call_fidelity', 'original_call', r(1))",
    "obligation('call_fidelity', 'original_call', z(1))",
    "",
    "// Proof statistics: recorded steps and how they were checked.",
    "steps(6)",
    "verified(2)",
    "recomputed(0)",
    "composed(0)",
    'trusted(4)',
    "claims(3)",
    "",
    "// This verdict applies to the claims above; it does not establish completeness.",
    "verdict(failed(12))",
  ]),
])

