conformance('C5: a state test re-decides as it was called', [
  spec('10.3, 11.6'),
  args("--check-proof proof.js --goal 'p(X)' program.js"),
  file('program.js', [
    "implied_by(p(X), [is_var(X), unify(X, 'a')])",
  ]),
  file('proof.js', [
    "p('a')",
    '',
    "step(p('a'), clause(1), {X: 'a'}, [is_var('a'), unify('a', 'a')])",
    "step(is_var('a'), called(is_var(A)), {}, [])",
    "step(unify('a', 'a'), 'builtin', {}, [])",
    '',
    "called(p(A), [p('a')])",
  ]),
  stdout([
    '// Checked answers: these follow from the input program.',
    "p('a')",
    '',
    '// C1-C10: resolution, acyclicity, justification, coverage, re-decision,',
    '// boundary consistency, relevance, witness integrity, search closure and call fidelity.',
    "condition('C1', 'resolution', 'ok', 1)",
    "condition('C2', 'well_founded', 'ok', 3)",
    "condition('C3', 'justification', 'ok', 3)",
    "condition('C4', 'coverage', 'ok', 3)",
    "condition('C5', 're_decision', 'ok', 2)",
    "condition('C6', 'boundary_consistency', 'ok', 0)",
    "condition('C7', 'relevance', 'ok', 4)",
    "condition('C8', 'witness_integrity', 'ok', 0)",
    "condition('C9', 'search_closure', 'ok', 0)",
    "condition('C10', 'call_fidelity', 'ok', 1)",
    '',
    '// Proof statistics: recorded steps and how they were checked.',
    'steps(3)',
    'verified(1)',
    'recomputed(2)',
    'composed(0)',
    'trusted(0)',
    'claims(1)',
    '',
    '// This verdict applies to the claims above; it does not establish completeness.',
    "verdict('checked')",
  ]),
])

